import{_ as e,o as t,c as r,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"模型组合与服务策略","description":"从系统约束设计模型角色、服务方式、路由、故障切换和供应商边界，形成可演进的模型组合。","frontmatter":{"title":"模型组合与服务策略","description":"从系统约束设计模型角色、服务方式、路由、故障切换和供应商边界，形成可演进的模型组合。","verified_at":"2026-08-06","source":["https://platform.openai.com/docs/guides/evals","https://www.nist.gov/itl/ai-risk-management-framework","https://huggingface.co/docs/transformers/index"],"article":{"type":"decision","structure":"decision"}},"headers":[],"relativePath":"py-agent/architecture/technology-product-design/model-selection.md","filePath":"py-agent/architecture/technology-product-design/model-selection.md","lastUpdated":1786083160000}'),n={name:"py-agent/architecture/technology-product-design/model-selection.md"};function l(o,a,h,d,s,p){return t(),r("div",null,[...a[0]||(a[0]=[i(`<h1 id="模型组合与服务策略" tabindex="-1">模型组合与服务策略 <a class="header-anchor" href="#模型组合与服务策略" aria-label="Permalink to &quot;模型组合与服务策略&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>架构层的模型决策不是从模型排行榜里挑一个名字，而是决定：系统需要哪些模型角色，它们通过什么服务形态提供，请求怎样路由，端点失效或质量不足时怎样降级，以及如何避免业务代码被某个供应商锁定。</p><p>单个候选怎样建立数据集、比较质量、延迟和成本，见<a href="/py-agent/foundations/model-application/model-selection-basic-evaluation">模型选型与基础评测</a>；模型网关怎样实现目录、路由、限流和熔断，见<a href="/py-agent/quality/model-serving-adaptation/model-gateway-routing-inference">模型网关与路由</a>。本章只负责两者之间的架构决策。</p><h2 id="_1-决策对象" tabindex="-1">1. 决策对象 <a class="header-anchor" href="#_1-决策对象" aria-label="Permalink to &quot;1. 决策对象&quot;">​</a></h2><h3 id="_1-1-模型不等于服务" tabindex="-1">1.1 模型不等于服务 <a class="header-anchor" href="#_1-1-模型不等于服务" aria-label="Permalink to &quot;1.1 模型不等于服务&quot;">​</a></h3><p>模型描述权重和能力，服务还包括供应商、区域、端点、推理引擎、版本策略、配额和数据处理条款。同一个模型由不同服务提供时，工具调用、结构化输出、上下文上限、延迟和错误语义都可能不同。</p><p>因此运行时选择的不是抽象的“某系列模型”，而是一个可定位的服务目标：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider + region + endpoint + model/revision</span></span>
<span class="line"><span>+ tokenizer/template + adapter + inference config</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h3 id="_1-2-单模型不等于单角色" tabindex="-1">1.2 单模型不等于单角色 <a class="header-anchor" href="#_1-2-单模型不等于单角色" aria-label="Permalink to &quot;1.2 单模型不等于单角色&quot;">​</a></h3><p>系统可以只部署一个模型，但仍应先定义它承担哪些角色，例如交互回答、复杂推理、结构化提取或安全复核。角色先于型号，后续才能判断某个角色是否值得拆出专用模型。</p><h3 id="_1-3-最终产物" tabindex="-1">1.3 最终产物 <a class="header-anchor" href="#_1-3-最终产物" aria-label="Permalink to &quot;1.3 最终产物&quot;">​</a></h3><p>模型策略应形成四项可执行产物：模型角色表、服务拓扑、路由与降级规则、复查条件。只有“主模型使用 X”不能指导故障处理、数据治理和版本演进。</p><h2 id="_2-架构约束" tabindex="-1">2. 架构约束 <a class="header-anchor" href="#_2-架构约束" aria-label="Permalink to &quot;2. 架构约束&quot;">​</a></h2><h3 id="_2-1-能力约束" tabindex="-1">2.1 能力约束 <a class="header-anchor" href="#_2-1-能力约束" aria-label="Permalink to &quot;2.1 能力约束&quot;">​</a></h3><p>记录每类任务需要的模态、语言、上下文、结构化输出、工具调用、流式和批处理能力。能力不满足是淘汰条件，不能用更低价格补偿。</p><h3 id="_2-2-数据与合规约束" tabindex="-1">2.2 数据与合规约束 <a class="header-anchor" href="#_2-2-数据与合规约束" aria-label="Permalink to &quot;2.2 数据与合规约束&quot;">​</a></h3><p>明确数据分类、允许地域、保留、训练使用、子处理者和许可证。敏感请求可能只能进入特定区域或私有端点；路由器必须在选择模型前执行这些硬规则。</p><h3 id="_2-3-可用性约束" tabindex="-1">2.3 可用性约束 <a class="header-anchor" href="#_2-3-可用性约束" aria-label="Permalink to &quot;2.3 可用性约束&quot;">​</a></h3><p>根据业务 SLO 判断是否需要多区域、备用端点或跨供应商容灾。若业务允许排队等待，增加实时备用模型未必值得；若高峰期仍需低延迟，就要同时验证配额、容量和故障余量。</p><h3 id="_2-4-组织与运营约束" tabindex="-1">2.4 组织与运营约束 <a class="header-anchor" href="#_2-4-组织与运营约束" aria-label="Permalink to &quot;2.4 组织与运营约束&quot;">​</a></h3><p>自托管模型要求硬件、推理优化、容量规划、安全修复和值班能力。数据可控不等于运营成本更低，团队无法承担这些责任时，自托管不是实际候选。</p><h2 id="_3-服务拓扑候选" tabindex="-1">3. 服务拓扑候选 <a class="header-anchor" href="#_3-服务拓扑候选" aria-label="Permalink to &quot;3. 服务拓扑候选&quot;">​</a></h2><h3 id="_3-1-单一托管端点" tabindex="-1">3.1 单一托管端点 <a class="header-anchor" href="#_3-1-单一托管端点" aria-label="Permalink to &quot;3.1 单一托管端点&quot;">​</a></h3><p>所有任务使用一个供应商和端点。它最容易建立基线，适合任务相近、风险较低且供应商 SLO 足够的系统。主要风险是配额、区域和供应商故障集中。</p><h3 id="_3-2-同供应商多端点" tabindex="-1">3.2 同供应商多端点 <a class="header-anchor" href="#_3-2-同供应商多端点" aria-label="Permalink to &quot;3.2 同供应商多端点&quot;">​</a></h3><p>同一供应商内使用多个模型、版本或区域。协议和运营相对统一，能分离快慢任务或提供区域冗余；但控制面、身份或供应商级故障仍可能同时影响全部端点。</p><h3 id="_3-3-多供应商组合" tabindex="-1">3.3 多供应商组合 <a class="header-anchor" href="#_3-3-多供应商组合" aria-label="Permalink to &quot;3.3 多供应商组合&quot;">​</a></h3><p>不同供应商承担主用、备用或专门任务。它能缩小供应商故障和商业变化的影响，但工具 Schema、结构化输出、内容策略和错误语义并不天然兼容，需要适配与独立评测。</p><h3 id="_3-4-自托管" tabindex="-1">3.4 自托管 <a class="header-anchor" href="#_3-4-自托管" aria-label="Permalink to &quot;3.4 自托管&quot;">​</a></h3><p>模型在自有或专属基础设施运行，适合必须控制数据路径、版本或推理栈的场景。除了 GPU 成本，还要承担制品来源、漏洞、容量、弹性、升级和恢复。</p><h3 id="_3-5-混合拓扑" tabindex="-1">3.5 混合拓扑 <a class="header-anchor" href="#_3-5-混合拓扑" aria-label="Permalink to &quot;3.5 混合拓扑&quot;">​</a></h3><p>托管端点处理通用任务，私有端点处理敏感数据，专用模型完成 Embedding、重排或分类。混合拓扑只有在任务或数据边界真实存在时才有价值，否则会增加路由、观测和回归矩阵。</p><h2 id="_4-模型角色" tabindex="-1">4. 模型角色 <a class="header-anchor" href="#_4-模型角色" aria-label="Permalink to &quot;4. 模型角色&quot;">​</a></h2><h3 id="_4-1-交互模型" tabindex="-1">4.1 交互模型 <a class="header-anchor" href="#_4-1-交互模型" aria-label="Permalink to &quot;4.1 交互模型&quot;">​</a></h3><p>负责首轮理解、澄清和低延迟回答。它优先满足响应速度、常用语言和稳定结构，而不必承担最复杂推理。</p><h3 id="_4-2-深度处理模型" tabindex="-1">4.2 深度处理模型 <a class="header-anchor" href="#_4-2-深度处理模型" aria-label="Permalink to &quot;4.2 深度处理模型&quot;">​</a></h3><p>用于复杂规划、长文综合或高难度代码分析。通常通过后台任务或升级路径调用，避免所有请求都支付最高延迟和成本。</p><h3 id="_4-3-专用模型" tabindex="-1">4.3 专用模型 <a class="header-anchor" href="#_4-3-专用模型" aria-label="Permalink to &quot;4.3 专用模型&quot;">​</a></h3><p>Embedding、重排、语音、视觉、分类和内容检测具有不同输入输出契约。不要因为都由“AI 模型”实现，就把它们塞进同一个聊天模型端口。</p><h3 id="_4-4-备用模型" tabindex="-1">4.4 备用模型 <a class="header-anchor" href="#_4-4-备用模型" aria-label="Permalink to &quot;4.4 备用模型&quot;">​</a></h3><p>备用模型的目标是维持明确的最低服务，而不是假装与主模型完全等价。必须说明它支持哪些任务、不能执行哪些工具，以及结果是否需要降级标记或人工复核。</p><h2 id="_5-路由策略" tabindex="-1">5. 路由策略 <a class="header-anchor" href="#_5-路由策略" aria-label="Permalink to &quot;5. 路由策略&quot;">​</a></h2><h3 id="_5-1-硬约束路由" tabindex="-1">5.1 硬约束路由 <a class="header-anchor" href="#_5-1-硬约束路由" aria-label="Permalink to &quot;5.1 硬约束路由&quot;">​</a></h3><p>先按地域、数据等级、模态、上下文和工具能力过滤端点。未满足硬约束的候选不能进入后续质量或成本比较。</p><h3 id="_5-2-任务路由" tabindex="-1">5.2 任务路由 <a class="header-anchor" href="#_5-2-任务路由" aria-label="Permalink to &quot;5.2 任务路由&quot;">​</a></h3><p>在合格端点中按任务类型、复杂度、交互/后台模式和风险选择角色。路由输入使用结构化元数据，不让模型自由决定敏感数据应发送到哪里。</p><h3 id="_5-3-升级路由" tabindex="-1">5.3 升级路由 <a class="header-anchor" href="#_5-3-升级路由" aria-label="Permalink to &quot;5.3 升级路由&quot;">​</a></h3><p>快速模型可先处理常规任务；当证据缺失、验证失败、工具参数反复修复或任务进入高风险 Slice 时，升级到更强模型或人工。升级必须有可观察触发器，不能只依赖模型自报置信度。</p><h3 id="_5-4-会话粘性" tabindex="-1">5.4 会话粘性 <a class="header-anchor" href="#_5-4-会话粘性" aria-label="Permalink to &quot;5.4 会话粘性&quot;">​</a></h3><p>多轮会话中途切换模型可能改变工具格式、语气和行为。一次任务应记录实际模型，并根据兼容性决定保持会话粘性还是允许显式升级。</p><h2 id="_6-故障切换与降级" tabindex="-1">6. 故障切换与降级 <a class="header-anchor" href="#_6-故障切换与降级" aria-label="Permalink to &quot;6. 故障切换与降级&quot;">​</a></h2><h3 id="_6-1-识别故障类型" tabindex="-1">6.1 识别故障类型 <a class="header-anchor" href="#_6-1-识别故障类型" aria-label="Permalink to &quot;6.1 识别故障类型&quot;">​</a></h3><p>认证错误、限流、超时、流式中断、结构化解析失败和质量验证失败不是同一种故障。只有暂时且替代端点能够安全处理的失败才适合自动切换。</p><h3 id="_6-2-兼容性检查" tabindex="-1">6.2 兼容性检查 <a class="header-anchor" href="#_6-2-兼容性检查" aria-label="Permalink to &quot;6.2 兼容性检查&quot;">​</a></h3><p>备用端点必须重新验证消息、工具 Schema、结构化输出、上下文、内容政策和数据地域。将相同请求直接转给另一个供应商，不代表语义保持一致。</p><h3 id="_6-3-降级等级" tabindex="-1">6.3 降级等级 <a class="header-anchor" href="#_6-3-降级等级" aria-label="Permalink to &quot;6.3 降级等级&quot;">​</a></h3><p>可预先定义：完整 Agent、只读问答、无工具草稿、排队等待、转人工和安全失败。高风险写任务在主模型不可用时，通常应暂停或转人工，而不是使用未验证模型继续执行。</p><h3 id="_6-4-状态与副作用" tabindex="-1">6.4 状态与副作用 <a class="header-anchor" href="#_6-4-状态与副作用" aria-label="Permalink to &quot;6.4 状态与副作用&quot;">​</a></h3><p>切换模型前保留任务 ID、已完成步骤、工具结果和副作用状态。备用模型只能从结构化状态继续，不能根据一段摘要猜测此前是否已经执行写操作。</p><h2 id="_7-供应商与运行时边界" tabindex="-1">7. 供应商与运行时边界 <a class="header-anchor" href="#_7-供应商与运行时边界" aria-label="Permalink to &quot;7. 供应商与运行时边界&quot;">​</a></h2><h3 id="_7-1-能力目录" tabindex="-1">7.1 能力目录 <a class="header-anchor" href="#_7-1-能力目录" aria-label="Permalink to &quot;7.1 能力目录&quot;">​</a></h3><p>为每个服务目标记录模态、上下文、工具、结构化输出、流式、地域、数据政策、配额、价格版本和生命周期。目录是路由输入，不是营销功能表。</p><h3 id="_7-2-内部模型端口" tabindex="-1">7.2 内部模型端口 <a class="header-anchor" href="#_7-2-内部模型端口" aria-label="Permalink to &quot;7.2 内部模型端口&quot;">​</a></h3><p>业务用例依赖内部的消息、结构化结果、工具提案、用量和错误契约，供应商 SDK 留在适配器。内部端口应表达业务真正使用的能力，而不是强行取所有供应商的最小交集。</p><h3 id="_7-3-差异显式化" tabindex="-1">7.3 差异显式化 <a class="header-anchor" href="#_7-3-差异显式化" aria-label="Permalink to &quot;7.3 差异显式化&quot;">​</a></h3><p>无法统一的能力用 Capability 或独立接口表达。例如实时音频和批量 Embedding 不应伪装成同一个 <code>chat()</code> 方法的可选参数。</p><h3 id="_7-4-运行证据" tabindex="-1">7.4 运行证据 <a class="header-anchor" href="#_7-4-运行证据" aria-label="Permalink to &quot;7.4 运行证据&quot;">​</a></h3><p>每次调用记录逻辑角色、路由原因、实际供应商、模型版本、策略版本、重试/切换和用量。否则质量变化无法归因到模型还是路由。</p><h2 id="_8-数据与租户治理" tabindex="-1">8. 数据与租户治理 <a class="header-anchor" href="#_8-数据与租户治理" aria-label="Permalink to &quot;8. 数据与租户治理&quot;">​</a></h2><p>路由决策接收可信的租户、地域和数据等级，不能从 Prompt 文本推断。模型输入在进入端点前完成最小化和脱敏，日志与失败回退沿用相同策略。</p><p>多租户共享模型网关时，分别限制请求、Token、并发和费用；缓存键必须包含租户与权限上下文。跨区域或跨供应商切换若改变数据处理条件，应直接禁止或要求重新授权。</p><h2 id="_9-容量与经济性" tabindex="-1">9. 容量与经济性 <a class="header-anchor" href="#_9-容量与经济性" aria-label="Permalink to &quot;9. 容量与经济性&quot;">​</a></h2><p>比较完整组合的每成功任务成本，而不是单次 Token 单价。路由分类、失败重试、升级调用、备用容量、人工接管和自托管闲置都属于模型策略成本。</p><p>容量规划按角色和故障场景进行：主端点失效时，备用端点能否承担允许降级后的流量；配额下降时，哪些租户和任务优先；长上下文任务是否挤占交互请求。这些决策应与<a href="/py-agent/quality/observability-performance/cost-budget-capacity">成本预算与容量</a>共享同一流量假设。</p><h2 id="_10-填写后的决策案例" tabindex="-1">10. 填写后的决策案例 <a class="header-anchor" href="#_10-填写后的决策案例" aria-label="Permalink to &quot;10. 填写后的决策案例&quot;">​</a></h2><p>场景：售后 Agent 同时提供政策问答和“确认后创建退款”。要求境内数据处理、首反馈 <code>p95 &lt;= 2s</code>，未确认写操作为零；长政策文档允许后台处理。</p><table tabindex="0"><thead><tr><th>候选</th><th>优点</th><th>关键问题</th><th>结论</th></tr></thead><tbody><tr><td>单一强模型</td><td>行为统一，设计最简单</td><td>常规问答延迟与成本偏高；单端点故障</td><td>不采用</td></tr><tr><td>快速模型 + 强模型</td><td>常规任务低延迟，复杂任务可升级</td><td>需要复杂度判断和会话粘性</td><td>主方案</td></tr><tr><td>两家供应商自动互备</td><td>缩小供应商故障</td><td>工具与数据政策差异，回归矩阵扩大</td><td>仅只读降级</td></tr><tr><td>全部自托管</td><td>数据路径可控</td><td>当前团队无 GPU 值班和容量能力</td><td>暂不采用</td></tr></tbody></table><p>最终策略：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>政策短问答 -&gt; 境内快速模型</span></span>
<span class="line"><span>长文综合或证据校验失败 -&gt; 境内强模型</span></span>
<span class="line"><span>退款动作提案 -&gt; 强模型生成结构化参数 -&gt; 业务规则与人工确认</span></span>
<span class="line"><span>主供应商故障 -&gt; 备用供应商仅提供只读回答并显示降级状态</span></span>
<span class="line"><span>所有写任务 -&gt; 暂停进入人工队列</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这个决定没有声称备用模型等价，而是明确缩小了故障时的产品承诺。</p><h2 id="_11-组合验证" tabindex="-1">11. 组合验证 <a class="header-anchor" href="#_11-组合验证" aria-label="Permalink to &quot;11. 组合验证&quot;">​</a></h2><p>基础评测证明单个候选是否合格；组合还要验证：</p><ul><li>硬约束路由是否从不把数据发送到不合规端点；</li><li>任务路由错误率以及错误对关键 Slice 的影响；</li><li>升级是否真正提高每成功任务质量；</li><li>主端点故障时降级状态、积压和恢复是否符合承诺；</li><li>多轮会话切换是否破坏工具与结构化结果；</li><li>Trace 是否能还原每次实际模型和路由原因。</li></ul><p>上线前用固定故障和任务集验证，生产中按角色、端点、租户和路由原因观察。路由器本身也是需要版本化和回归的决策组件。</p><h2 id="_12-决策记录与复查" tabindex="-1">12. 决策记录与复查 <a class="header-anchor" href="#_12-决策记录与复查" aria-label="Permalink to &quot;12. 决策记录与复查&quot;">​</a></h2><p>ADR 至少记录：任务角色、硬约束、候选拓扑、选定服务、路由规则、备用能力、数据边界、容量假设、验证证据、负面后果和退出条件。</p><p>模型下线、价格或条款变化、数据分布漂移、流量增长、新增高风险工具以及团队获得自托管能力时，都应触发复查。模型策略的目标不是永久选中一个品牌，而是在约束变化时仍能替换、降级并解释系统行为。</p>`,88)])])}const b=e(n,[["render",l]]);export{u as __pageData,b as default};
